// wf.profile.extract > "Call input"
// Input: {text, jurisdiction (account), today, model?, version?} and the jurisdiction's
// extraction context (currencies and exponents, allowed preference filters).
const s = $('Start').first().json;
const c = $input.first().json.ctx || {};
return [{ json: { prompt: 'P2_profile_extractor', version: s.version ?? null, model: s.model || null,
  vars: { message: s.text, jurisdiction: s.jurisdiction, today: s.today, default_currency: c.default_currency,
          currency_exponents: c.currencies, allowed_preferences: c.allowed_preference_filters },
  meta: { jurisdiction: s.jurisdiction, ctx: c } } }];

// wf.profile.extract > "Check profile"
// Deterministic checks after P2 (spec 8.2 A2 guardrail, 4.4): preferences outside the
// jurisdiction's allowed list are moved to unparsed; a stated amount without a currency gets
// the jurisdiction's currency; an unknown currency or a reversed range is flagged. Warnings
// are codes, never sentences (spec 17.1). From P2 v3 the model gives amounts in main units and
// they are converted to minor units first (D-066, lib/money.js).
// Budget amounts from P2 v3 (D-066). From v3 the model returns budget_min / budget_max in the
// currency's main unit (450 for 450 dinars) and this code converts them to the minor units the
// profile stores, with the exponent from app.currencies. In v2 the model did the conversion and
// made power-of-ten errors. Outputs without budget_min / budget_max (v1, v2) pass unchanged.
//
// out: the validated model output; exponents: {currency: exponent}; fallbackCurrency: the
// currency used when an amount has none (the jurisdiction's, as the prompt's rule 2 says).
// The currency field itself is not filled here: that stays a model output (and a warning in
// the profile workflow), so the evaluation still scores what the model said.
function amountsToMinor(out, exponents, fallbackCurrency) {
  if (!out || typeof out !== 'object' || !('budget_min' in out || 'budget_max' in out)) return out;
  const cur = out.currency || fallbackCurrency || null;
  const has = cur !== null && exponents && Object.prototype.hasOwnProperty.call(exponents, cur);
  const exp = has ? Number(exponents[cur]) : null;
  const toMinor = (v) => {
    if (v === null || v === undefined || exp === null) return null;
    const n = Number(v);
    return Number.isFinite(n) && n >= 0 ? Math.round(n * Math.pow(10, exp)) : null;
  };
  const rename = { budget_min: 'budget_min_minor', budget_max: 'budget_max_minor' };
  const p = {};
  for (const [k, v] of Object.entries(out)) {
    if (k in rename) p[rename[k]] = toMinor(v);
    else if (k === 'field_confidence' && v && typeof v === 'object') {
      p[k] = Object.fromEntries(Object.entries(v).map(([fk, fv]) => [rename[fk] || fk, fv]));
    } else p[k] = v;
  }
  return p;
}

if (typeof module !== 'undefined') module.exports = { amountsToMinor };

const r = $input.first().json;
const ctx = (r.meta && r.meta.ctx) || {};
const step = { agent: 'A2_profile', prompt_version_id: r.prompt_version_id || null, model: r.model || null,
  input: { chars: String($('Start').first().json.text || '').length, jurisdiction: r.meta && r.meta.jurisdiction },
  output: r.ok ? r.output : { error_code: r.error_code }, latency_ms: r.latency_ms, tokens_in: r.tokens_in || 0,
  tokens_out: r.tokens_out || 0, error: r.ok ? null : `${r.error_code}${r.detail ? ': ' + String(r.detail).slice(0, 200) : ''}` };
if (!r.ok) {
  return [{ json: { ok: false, error_code: r.call_error ? 'UPSTREAM_UNAVAILABLE' : 'EXTRACTION_FAILED', steps: [step], anchor_label: null } }];
}
const p = amountsToMinor(JSON.parse(JSON.stringify(r.output)), ctx.currencies || {}, ctx.default_currency || null);
const warnings = [];
const allowed = new Set((ctx.allowed_preference_filters || []).map(String));
for (const k of Object.keys(p.declared_preferences || {})) {
  if (!allowed.has(k)) {
    p.unparsed = [...(p.unparsed || []), `${k}: ${p.declared_preferences[k]}`];
    delete p.declared_preferences[k];
    warnings.push('preference_not_allowed');
  }
}
const currencies = ctx.currencies || {};
const hasAmount = p.budget_min_minor !== null || p.budget_max_minor !== null;
if (hasAmount && !p.currency) {
  p.currency = ctx.default_currency || null;
  warnings.push('currency_assumed');
}
if (p.currency && !Object.prototype.hasOwnProperty.call(currencies, p.currency)) {
  warnings.push('currency_unknown');
  p.budget_min_minor = null; p.budget_max_minor = null; p.currency = null; p.budget_period = null;
}
if (hasAmount && !p.budget_period) p.budget_period = 'month';
if (p.budget_min_minor !== null && p.budget_max_minor !== null && p.budget_min_minor > p.budget_max_minor) {
  [p.budget_min_minor, p.budget_max_minor] = [p.budget_max_minor, p.budget_min_minor];
  warnings.push('budget_range_reversed');
}
// The search runs in the jurisdiction the request names, else the account's.
const search_jurisdiction = p.jurisdiction_code || (r.meta && r.meta.jurisdiction) || null;
return [{ json: { ok: true, profile: p, search_jurisdiction, warnings, steps: [step],
  anchor_label: p.anchor_label || '', geo_jurisdiction: search_jurisdiction || '' } }];

// wf.profile.extract > "Result"
// Adds the geocoded anchor (app.geocode) to the checked profile.
const x = $('Check profile').first().json;
if (!x.ok) return [{ json: x }];
const g = $input.first().json.g || null;
const warnings = [...x.warnings];
let anchor = null;
if (g) {
  anchor = { status: g.status, place: g.place || null, candidates: g.status === 'ambiguous' ? g.candidates : [] };
  if (g.status !== 'found') warnings.push(`anchor_${g.status}`);
}
const steps = [...x.steps];
if (g) steps.push({ agent: 'A2_profile', model: null, input: { tool: 'app.geocode', jurisdiction: x.geo_jurisdiction },
  output: { status: g.status, place_key: g.place ? g.place.place_key : null }, tool_calls: [{ tool: 'app.geocode' }] });
return [{ json: { ok: true, profile: x.profile, search_jurisdiction: x.search_jurisdiction, anchor, warnings, steps } }];
